local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")

local player = Players.LocalPlayer
local character = player.Character or player.CharacterAdded:Wait()
local humanoid = character:WaitForChild("Humanoid")
local hrp = character:WaitForChild("HumanoidRootPart")

player.CharacterAdded:Connect(function(char)
	character = char
	humanoid = char:WaitForChild("Humanoid")
	hrp = char:WaitForChild("HumanoidRootPart")
end)

local gui = Instance.new("ScreenGui")
gui.Name = "FlyGUIV3_Cyberpunk"
gui.ResetOnSpawn = false
gui.Parent = player.PlayerGui

-- Main Frame: Tinh chỉnh UI siêu đẹp, hiệu ứng kính mờ (Glassmorphism + Neon Cyberpunk)
local frame = Instance.new("Frame")
frame.Size = UDim2.new(0, 250, 0, 130)
frame.Position = UDim2.new(0.35, 0, 0.3, 0)
frame.BackgroundColor3 = Color3.fromRGB(13, 13, 18)
frame.BackgroundTransparency = 0.15
frame.BorderSizePixel = 0
frame.Active = true
frame.Draggable = true
frame.Parent = gui

local frameCorner = Instance.new("UICorner")
frameCorner.CornerRadius = UDim.new(0, 14)
frameCorner.Parent = frame

-- Viền phát sáng Neon đa sắc/tím hồng rực rỡ
local frameStroke = Instance.new("UIStroke")
frameStroke.Color = Color3.fromRGB(255, 0, 128)
frameStroke.Thickness = 2.5
frameStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
frameStroke.Parent = frame

-- Title Bar sành điệu
local title = Instance.new("TextLabel")
title.Text = "★彡 Рussу Uиkиоши 彡모"
title.Size = UDim2.new(1, 0, 0, 34)
title.Position = UDim2.new(0, 0, 0, 0)
title.BackgroundColor3 = Color3.fromRGB(40, 10, 45)
title.BackgroundTransparency = 0.4
title.TextSize = 13
title.Font = Enum.Font.GothamBold
title.TextColor3 = Color3.fromRGB(255, 110, 220)
title.BorderSizePixel = 0
title.Parent = frame

local titleCorner = Instance.new("UICorner")
titleCorner.CornerRadius = UDim.new(0, 14)
titleCorner.Parent = title

-- Hàm tạo Button siêu mượt với hiệu ứng Nhún & Sáng khi chạm
local function CreateButton(text, pos, size, bgCol, textCol)
	local b = Instance.new("TextButton")
	b.Text = text
	b.BackgroundColor3 = bgCol
	b.Position = pos
	b.Size = size
	b.Font = Enum.Font.GothamBold
	b.TextSize = 14
	b.TextColor3 = textCol
	b.BorderSizePixel = 0
	b.AutoButtonColor = false
	b.Parent = frame

	local btnCorner = Instance.new("UICorner")
	btnCorner.CornerRadius = UDim.new(0, 8)
	btnCorner.Parent = b

	local btnStroke = Instance.new("UIStroke")
	btnStroke.Color = Color3.fromRGB(255, 255, 255)
	btnStroke.Transparency = 0.7
	btnStroke.Thickness = 1
	btnStroke.Parent = b

	b.MouseEnter:Connect(function()
		TweenService:Create(b, TweenInfo.new(0.2), {BackgroundTransparency = 0.3}):Play()
	end)
	b.MouseLeave:Connect(function()
		TweenService:Create(b, TweenInfo.new(0.2), {BackgroundTransparency = 0}):Play()
	end)

	return b
end

-- Nút Giảm Speed (-)
local minusBtn = CreateButton(
	"-",
	UDim2.new(0, 12, 0, 44),
	UDim2.new(0, 40, 0, 32),
	Color3.fromRGB(239, 68, 68),
	Color3.fromRGB(255, 255, 255)
)

-- Label Tốc Độ (Speed Display)
local speedLabel = Instance.new("TextLabel")
speedLabel.Size = UDim2.new(0, 134, 0, 32)
speedLabel.Position = UDim2.new(0, 58, 0, 44)
speedLabel.BackgroundColor3 = Color3.fromRGB(25, 25, 35)
speedLabel.BackgroundTransparency = 0.3
speedLabel.Font = Enum.Font.GothamBold
speedLabel.TextSize = 12
speedLabel.TextColor3 = Color3.fromRGB(0, 245, 255)
speedLabel.BorderSizePixel = 0
speedLabel.Parent = frame

local speedCorner = Instance.new("UICorner")
speedCorner.CornerRadius = UDim.new(0, 8)
speedCorner.Parent = speedLabel

local speedStroke = Instance.new("UIStroke")
speedStroke.Color = Color3.fromRGB(0, 245, 255)
speedStroke.Transparency = 0.5
speedStroke.Thickness = 1
speedStroke.Parent = speedLabel

-- Nút Tăng Speed (+)
local plusBtn = CreateButton(
	"+",
	UDim2.new(0, 198, 0, 44),
	UDim2.new(0, 40, 0, 32),
	Color3.fromRGB(34, 197, 94),
	Color3.fromRGB(255, 255, 255)
)

-- Nút Fly / Unfly (Đậm chất Cyberpunk)
local flyBtn = CreateButton(
	"🚀 FLY (OFF)",
	UDim2.new(0, 12, 0, 84),
	UDim2.new(0, 226, 0, 36),
	Color3.fromRGB(140, 0, 255),
	Color3.fromRGB(255, 255, 255)
)

local flying = false
local speed = 1
speedLabel.Text = "SPEED: " .. tostring(speed)

local bv
local bg
local noclipConn

plusBtn.MouseButton1Click:Connect(function()
	speed += 1
	speedLabel.Text = "SPEED: " .. tostring(speed)
end)

minusBtn.MouseButton1Click:Connect(function()
	speed = math.max(1, speed - 1)
	speedLabel.Text = "SPEED: " .. tostring(speed)
end)

flyBtn.MouseButton1Click:Connect(function()
	flying = not flying
	if flying then
		flyBtn.Text = "🔥 UNFLY (ON)"
		flyBtn.BackgroundColor3 = Color3.fromRGB(225, 29, 72)
		frameStroke.Color = Color3.fromRGB(0, 255, 128) -- Đổi viền sang xanh lá neon khi bật fly
		
		bv = Instance.new("BodyVelocity")
		bv.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
		bv.Velocity = Vector3.zero
		bv.Parent = hrp
		
		bg = Instance.new("BodyGyro")
		bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
		bg.P = 10000
		bg.Parent = hrp
		
		humanoid.PlatformStand = true
		
		-- Bật xuyên tường (Noclip)
		noclipConn = RunService.Stepped:Connect(function()
			if character then
				for _, part in pairs(character:GetDescendants()) do
					if part:IsA("BasePart") then
						part.CanCollide = false
					end
				end
			end
		end)
	else
		flyBtn.Text = "🚀 FLY (OFF)"
		flyBtn.BackgroundColor3 = Color3.fromRGB(140, 0, 255)
		frameStroke.Color = Color3.fromRGB(255, 0, 128) -- Trả lại viền hồng tím
		
		if bv then bv:Destroy() end
		if bg then bg:Destroy() end
		
		-- Tắt xuyên tường
		if noclipConn then
			noclipConn:Disconnect()
			noclipConn = nil
		end
		
		if character then
			for _, part in pairs(character:GetDescendants()) do
				if part:IsA("BasePart") then
					part.CanCollide = true
				end
			end
		end
		
		humanoid.PlatformStand = false
	end
end)

RunService.RenderStepped:Connect(function()
	if flying and hrp and humanoid and bv and bg then
		local cam = workspace.CurrentCamera
		local move = humanoid.MoveDirection
		local localMove = hrp.CFrame:VectorToObjectSpace(move)
		local velocity =
			(hrp.CFrame.LookVector * -localMove.Z) +
			(hrp.CFrame.RightVector * localMove.X)
		if velocity.Magnitude > 0 then
			velocity = velocity.Unit
		end
		bv.Velocity = velocity * (speed * 20)
		bg.CFrame = cam.CFrame
	end
end)
